"""Task G small read-only checks (reviewer). Imports the author's measure module without running main(); writes only to the scratchpad.
Not a reproduction of the author's run: no search, no intersections, no gaps."""
import sys, os, json, math, importlib.util, hashlib, time
sys.dont_write_bytecode = True
import numpy as np

STUDIO = sys.argv[1]
OUT = sys.argv[2]
T0 = time.time()
p = os.path.join(STUDIO, 'asset-pipeline', 'full-kit', 'source', 'measure_fullkit_m4_v03.py')
spec = importlib.util.spec_from_file_location('m4measure', p)
M = importlib.util.module_from_spec(spec)
spec.loader.exec_module(M)
G3, G1 = M.G3, M.G1
res = {'measureScriptSha256': hashlib.sha256(open(p, 'rb').read()).hexdigest()}

parts3, _ = G3.build_all()
parts1, _ = G1.build_all()


def vis(parts, row, pts, kept=None):
    saved = dict(M.KEPT)
    try:
        if kept is not None:
            for k in list(M.KEPT):
                if not kept(k):
                    del M.KEPT[k]
        R = M.Rays(parts)
        hits = R.first(pts)
    finally:
        M.KEPT.clear()
        M.KEPT.update(saved)
    bl = {}
    for h in hits:
        if h not in (row, None):
            bl[h] = bl.get(h, 0) + 1
    return {'unobstructed': sum(h in (row, None) for h in hits), 'of': len(hits), 'blockers': bl}, hits


def feat(parts, name):
    row, cond = M.FEATURES[name]
    V = [v for v in parts[row].v if cond(v)]
    return row, V[::max(1, len(V) // 150)]


no_decal = lambda k: not k.startswith('contact_decals')
fv = {}
for tag, parts in (('v01', parts1), ('v03', parts3)):
    fv[tag] = {}
    for name in ('hihatPedal', 'throneSeat', 'sustainPedal', 'kickPedal'):
        row, pts = feat(parts, name)
        a, _ = vis(parts, row, pts)
        b, _ = vis(parts, row, pts, no_decal)
        fv[tag][name] = {'authorMethod': a, 'contactDecalsNotOccluders': b}
res['featureVisibility'] = fv

# which hi-hat pedal sub-parts carry the samples, v03 (labels) with and without decals as occluders
row = 'drum_hihat_pedal__pedal'
part = parts3[row]
V = np.asarray(part.v, float)
lab_of_v = {}
for lab, v0, v1, f0, f1 in part.groups:
    for i in range(v0, v1):
        lab_of_v[i] = lab
by = {}
a, hits = vis(parts3, row, V)
b, hits2 = vis(parts3, row, V, no_decal)
for i in range(len(V)):
    d = by.setdefault(lab_of_v.get(i, '?'), {'vertices': 0, 'authorMethodClear': 0, 'noDecalClear': 0, 'zMin': 9.0, 'zMax': -9.0})
    d['vertices'] += 1
    d['authorMethodClear'] += hits[i] in (row, None)
    d['noDecalClear'] += hits2[i] in (row, None)
    d['zMin'], d['zMax'] = min(d['zMin'], float(V[i, 2])), max(d['zMax'], float(V[i, 2]))
res['hihatPedalAllVerticesByLabelV03'] = {'all': a, 'allNoDecal': b, 'byLabel': by}
dec = {k: {'zMin': float(t.reshape(-1, 3)[:, 2].min()), 'zMax': float(t.reshape(-1, 3)[:, 2].max()),
           'xMin': float(t.reshape(-1, 3)[:, 0].min()), 'xMax': float(t.reshape(-1, 3)[:, 0].max()),
           'yMin': float(t.reshape(-1, 3)[:, 1].min()), 'yMax': float(t.reshape(-1, 3)[:, 1].max())}
       for k, (t, _) in M.KEPT.items() if k.startswith('contact_decals')}
res['contactDecalBounds'] = dec
res['onRugZ'] = float(G3.ON_RUG)
res['rugFieldTopZ'] = float(G3.RT)

# throne seat: area samples on the top disc and on the side band, v01 and v03 placements
t = G3.THRONE
ang = np.linspace(0, 2 * math.pi, 72, endpoint=False)
top = [(t['cx'] + r * math.cos(a_), t['cy'] + r * math.sin(a_), t['seat'] + 0.0025) for r in np.sqrt(np.linspace(0.02, 1, 12)) * (t['r'] - 0.03) for a_ in ang]
side = [(t['cx'] + (t['r'] + 0.0005) * math.cos(a_), t['cy'] + (t['r'] + 0.0005) * math.sin(a_), z) for z in (t['seat'] - 0.055, t['seat'] - 0.04, t['seat'] - 0.025) for a_ in ang]
thr = {}
for tag, parts in (('v01', parts1), ('v03', parts3)):
    thr[tag] = {}
    for nm, pts in (('topDisc', top), ('sideBand', side)):
        a, hits = vis(parts, 'drum_throne__throne', np.array(pts))
        thr[tag][nm] = a
        if nm == 'topDisc':
            P = np.array(pts)
            clear = np.array([h in ('drum_throne__throne', None) for h in hits])
            px = {}
            for c in ('music-1440', 'right-down'):
                pr, W, H = M.CAMS[c]
                q_all, q = pr(P), pr(P[clear])
                px[c] = {'discBBoxPx': [float(x) for x in (q_all[:, 0].min(), q_all[:, 1].min(), q_all[:, 0].max(), q_all[:, 1].max())],
                         'clearBBoxPx': [float(x) for x in (q[:, 0].min(), q[:, 1].min(), q[:, 0].max(), q[:, 1].max())] if len(q) else None}
            thr[tag]['topDiscPx'] = px
res['throneSeatAreaSamples'] = thr

# hard-edge accounting bands per row / label (builder split rule 40 deg; receipt counts only convex >= 80 deg)
bands = {}
comp_kick = {}
cable = {}
for row, part in parts3.items():
    V = np.asarray(part.v, float)
    F = [f for f, _ in part.f]
    nrm, _ = M.face_normals(V, F)
    lab_of = {}
    for lab, v0, v1, f0, f1 in part.groups:
        for fi in range(f0, f1):
            lab_of[fi] = lab
    edges = {}
    for fi, f in enumerate(F):
        for i in range(len(f)):
            a_, b_ = f[i - 1], f[i]
            edges.setdefault((min(a_, b_), max(a_, b_)), []).append(fi)
    # union-find over vertices for component identification
    par = list(range(len(V)))

    def root(x):
        while par[x] != x:
            par[x] = par[par[x]]
            x = par[x]
        return x
    for f in F:
        for i in range(1, len(f)):
            par[root(f[i])] = root(f[0])
    out = {}
    for (a_, b_), fs in edges.items():
        if len(fs) != 2:
            continue
        angd = math.degrees(math.acos(max(-1.0, min(1.0, float(np.dot(nrm[fs[0]], nrm[fs[1]]))))))
        if angd <= 40.0:
            continue
        L = float(np.linalg.norm(V[a_] - V[b_]))
        C0, C1 = V[list(F[fs[0]])].mean(0), V[list(F[fs[1]])].mean(0)
        convex = float(np.dot(nrm[fs[0]], C1 - C0)) < 1e-9
        lab = lab_of[fs[0]]
        key = ('convex>=80' if angd >= 80 else 'convex40to80') if convex else 'concave>40'
        d = out.setdefault(lab, {})
        d[key] = d.get(key, 0.0) + L
        d[key + 'Edges'] = d.get(key + 'Edges', 0) + 1
        if convex and angd >= 80 and lab in ('kick.hardware', 'hihat.hardware', 'module.controls', 'module.mount', 'stool', 'throne', 'stand', 'ctl.controls'):
            c = root(a_)
            e = comp_kick.setdefault(lab, {}).setdefault(c, {'lengthM': 0.0, 'edges': 0})
            e['lengthM'] += L
            e['edges'] += 1
        if convex and angd >= 80 and lab.startswith('cable.'):
            e = cable.setdefault(lab, {'capLike(<=0.01m)': [0, 0.0], 'runEdges(>0.01m)': [0, 0.0], 'maxEdgeM': 0.0})
            k = 'capLike(<=0.01m)' if L <= 0.01 else 'runEdges(>0.01m)'
            e[k][0] += 1
            e[k][1] += L
            e['maxEdgeM'] = max(e['maxEdgeM'], L)
    bands[row] = {k: {kk: (round(vv, 4) if isinstance(vv, float) else vv) for kk, vv in v.items()} for k, v in sorted(out.items())}
    # component descriptions
    for lab, comps in comp_kick.items():
        for c, e in comps.items():
            if 'bbox' in e or root(c) != c:
                continue
            idx = [i for i in range(len(V)) if root(i) == c]
            if not idx:
                continue
            P = V[idx]
            if lab_of_row := row:
                e['row'] = row
            e['bbox'] = [round(float(x), 4) for x in (P.max(0) - P.min(0))]
            e['centre'] = [round(float(x), 4) for x in (P.max(0) + P.min(0)) / 2]
            e['vertices'] = len(idx)
res['sharpSplitEdgeBandsByRowLabelM'] = bands
res['hardConvex80ByComponent'] = {lab: sorted([{**e, 'lengthM': round(e['lengthM'], 4)} for e in comps.values()], key=lambda e: -e['lengthM']) for lab, comps in comp_kick.items()}
res['cableHardConvex80Split'] = cable
tot = {'convex>=80': 0.0, 'convex40to80': 0.0, 'concave>40': 0.0}
for row, labs in bands.items():
    for lab, d in labs.items():
        for k in tot:
            tot[k] += d.get(k, 0.0)
res['sharpSplitEdgeTotalsM'] = {k: round(v, 3) for k, v in tot.items()}

# rug record and rack feet margins
res['rugRecord'] = M.rug_record()
rk = np.asarray(parts3['drum_rack__rack'].v, float)
low = rk[rk[:, 2] < rk[:, 2].min() + 0.03]
R = G3.RUG
res['rackLowPartsExtents'] = {'x': [float(low[:, 0].min()), float(low[:, 0].max())], 'y': [float(low[:, 1].min()), float(low[:, 1].max())],
                              'marginsM': {'left': float(low[:, 0].min() - R['x0']), 'right': float(R['x1'] - low[:, 0].max()),
                                           'front': float(low[:, 1].min() - R['y0']), 'back': float(R['y1'] - low[:, 1].max())},
                              'wallY': float(G3.WALL_Y), 'rackY': float(G3.RACK_Y)}
rk1 = np.asarray(parts1['drum_rack__rack'].v, float)
low1 = rk1[rk1[:, 2] < rk1[:, 2].min() + 0.03]
res['rackLowPartsExtentsV01'] = {'x': [float(low1[:, 0].min()), float(low1[:, 0].max())], 'y': [float(low1[:, 1].min()), float(low1[:, 1].max())]}
res['elapsedSeconds'] = round(time.time() - T0, 1)
json.dump(res, open(OUT, 'w', encoding='utf-8'), indent=1, default=str)
print('ok', res['elapsedSeconds'])
